function Initialize-AI5ArtifactReturn {param([string]$ServerRoot);$script:ArtifactRoot=Join-Path $ServerRoot 'runtime\artifacts';$script:ArtifactRegistry=Join-Path $script:ArtifactRoot 'registry';$script:ArtifactStore=Join-Path $script:ArtifactRoot 'store';@($script:ArtifactRoot,$script:ArtifactRegistry,$script:ArtifactStore)|ForEach-Object{New-Item -ItemType Directory -Force $_|Out-Null}}
function Get-AI5ArtifactKey($Manifest){foreach($v in @($Manifest.TASK_ID,$Manifest.CORRELATION_ID,$Manifest.ARTIFACT_ID)){if([string]$v-notmatch'^[A-Za-z0-9._-]+$'){throw 'invalid_artifact_identity'}};"$($Manifest.TASK_ID)--$($Manifest.CORRELATION_ID)--$($Manifest.ARTIFACT_ID)--$(([string]$Manifest.SHA256).ToLowerInvariant())"}
function Test-AI5ArtifactManifest($Manifest){$required=@('TASK_ID','CORRELATION_ID','ARTIFACT_ID','FILENAME','SHA256','BYTES','MEDIA_TYPE','SOURCE_AGENT','RETURN_ROUTE');foreach($name in $required){if(!$Manifest.psobject.Properties[$name]){throw "artifact_manifest_missing_$name"}};if([string]$Manifest.FILENAME-match'[/\\]' -or [string]$Manifest.FILENAME-in@('.','..')){throw 'unsafe_artifact_filename'};if([string]$Manifest.SHA256-notmatch'^[A-Fa-f0-9]{64}$'){throw 'invalid_artifact_sha256'};if([long]$Manifest.BYTES-lt1-or[long]$Manifest.BYTES-gt536870912){throw 'artifact_size_rejected'};if([string]$Manifest.RETURN_ROUTE-notin@('RESULT_BUS','PRIVATE_GITHUB')){throw 'artifact_route_rejected'};$true}
function Test-AI5ZipSafety {param([string]$Path,[int]$MaxEntries=2000,[long]$MaxUncompressedBytes=1073741824);Add-Type -AssemblyName System.IO.Compression.FileSystem;$zip=[IO.Compression.ZipFile]::OpenRead($Path);try{$total=[long]0;if($zip.Entries.Count-gt$MaxEntries){throw 'zip_entry_limit'};foreach($entry in $zip.Entries){$name=[string]$entry.FullName;if([IO.Path]::IsPathRooted($name)-or$name-match'(^|[\\/])\.\.([\\/]|$)' -or$name.Contains([char]0)){throw 'zip_path_traversal'};$total+=[long]$entry.Length;if($total-gt$MaxUncompressedBytes){throw 'zip_uncompressed_limit'};if($entry.CompressedLength-gt0-and$entry.Length/$entry.CompressedLength-gt200){throw 'zip_ratio_limit'}};[ordered]@{safe=$true;entries=$zip.Entries.Count;uncompressed_bytes=$total}}finally{$zip.Dispose()}}
function Register-AI5ReturnedArtifact {param($Manifest,[string]$SourcePath);Test-AI5ArtifactManifest $Manifest|Out-Null;if(!(Test-Path -LiteralPath $SourcePath -PathType Leaf)){throw 'artifact_source_missing'};$file=Get-Item -LiteralPath $SourcePath;if($file.Length-ne[long]$Manifest.BYTES){throw 'artifact_size_mismatch'};$actual=(Get-FileHash -LiteralPath $SourcePath -Algorithm SHA256).Hash.ToLowerInvariant();if($actual-ne([string]$Manifest.SHA256).ToLowerInvariant()){throw 'artifact_sha_mismatch'};$zipEvidence=$null;if($Manifest.FILENAME-match'(?i)\.zip$'){$zipEvidence=Test-AI5ZipSafety $SourcePath};$key=Get-AI5ArtifactKey $Manifest;$receipt=Join-Path $script:ArtifactRegistry "$key.json";$destination=Join-Path $script:ArtifactStore "$key--$($Manifest.FILENAME)";$record=[ordered]@{task_id=$Manifest.TASK_ID;correlation_id=$Manifest.CORRELATION_ID;artifact_id=$Manifest.ARTIFACT_ID;filename=$Manifest.FILENAME;sha256=$actual;bytes=$file.Length;source_agent=$Manifest.SOURCE_AGENT;return_route=$Manifest.RETURN_ROUTE;stored_path=$destination;zip_safety=$zipEvidence;registered_at=[DateTime]::UtcNow.ToString('o')};try{$bytes=[Text.Encoding]::UTF8.GetBytes(($record|ConvertTo-Json -Depth 10));$stream=[IO.File]::Open($receipt,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::None);try{$stream.Write($bytes,0,$bytes.Length);$stream.Flush($true)}finally{$stream.Dispose()}}catch [IO.IOException]{return [ordered]@{registered=$false;duplicate=$true;receipt=$receipt}};Copy-Item -LiteralPath $SourcePath -Destination $destination -ErrorAction Stop;[ordered]@{registered=$true;duplicate=$false;receipt=$receipt;stored_path=$destination;sha256=$actual;zip_safety=$zipEvidence}}
